        return '\n'.join(result)

    return "-1"


def dfs_path(adj, n, k):
    """Find a simple path of length at least n/k"""
    min_len = (n + k - 1) // k  # ceiling of n/k

    visited = [False] * (n + 1)

    def dfs(u, path, visited_local):
        if len(path) >= min_len:
            return path
        for v in adj[u]:
            if v not in visited_local:
                visited_local.add(v)
                new_path = path + [v]
                result = dfs(v, new_path, visited_local)
                if result is not None:
                    return result
                visited_local.remove(v)
        return None

    for start in range(1, n + 1):
        visited_local = {start}
        result = dfs(start, [start], visited_local)
        if result is not None:
            return result

    return None


def dfs_path_iterative(adj, n, k):
    """Iterative DFS to find a path"""
    min_len = (n + k - 1) // k

    stack = [(1, {1}, [1])]
    tried = set()

    while stack:
        u, visited, path = stack.pop()
        if len(path) >= min_len:
            return path
        for v in adj[u]:
            if v not in visited:
                key = (min(u, v), max(u, v))
                if key not in tried:
                    tried.add(key)
                    stack.append((v, visited | {v}, path + [v]))
    return None


