                    conflict[idx][other_idx] = True
                    conflict[other_idx][idx] = True

    # Now we have conflict matrix. Find maximum independent set
    # Use bitmask with branch and bound

    max_size = 0

    def backtrack(idx, current_mask, current_size, remaining_count):
        nonlocal max_size

        # Pruning
        if current_size + remaining_count <= max_size:
            return

        # Base case
        if idx == m:
            max_size = max(max_size, current_size)
            return

        # Try including friend idx if possible
        if not (current_mask & (1 << idx)):
            # Check if idx conflicts with any already selected friends
            conflict_mask = 0
            for neighbor in range(m):
