            if not (current_mask & conflict_mask):
                # Include idx
                new_mask = current_mask | (1 << idx)
                remaining = remaining_count - 1
                backtrack(idx + 1, new_mask, current_size + 1, remaining)

        # Try not including idx
        backtrack(idx + 1, current_mask, current_size, remaining_count - 1)

    backtrack(0, 0, 0, m)

    return str(max_size)

