def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].strip()
    if not first_line:
        return '0\n'
    n, m = map(int, first_line.split())

    if n == 0 or m == 0:
        return '0\n'

    total_cells = n * m

    # For each cell, determine valid destination cells (including stay)
    def get_destinations(r, c):
        dests = [(r, c)]  # stay in place
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                dests.append((nr, nc))
        return dests

    # Build bipartite graph adjacency
    # Left side: spiders at each cell (total_cells nodes)
    # Right side: destination cells (total_cells nodes)
    # Edge from i to j if spider at i can move to destination j

    adj = {}
    for r in range(n):
        for c in range(m):
            start_idx = r * m + c
            adj[start_idx] = set()

    for r in range(n):
        for c in range(m):
            start_idx = r * m + c
            for dest_r, dest_c in get_destinations(r, c):
                dest_idx = dest_r * m + dest_c
                adj[start_idx].add(dest_idx)

    # Maximum bipartite matching using DFS
    match = {}  # dest_idx -> spider_idx
    vis_iteration = [0]

    def dfs(u):
        for v in adj[u]:
            if vis_iteration[0] != v:
                vis_iteration[0] = v + 1
                if v not in match or dfs(match[v]):
                    match[v] = u
                    return True
        return False

    matching_size = 0
    vis_iteration[0] = 0

    for u in range(total_cells):
        vis_iteration[0] = 0
        if dfs(u):
            matching_size += 1

    # The minimum number of cells that must be occupied is equal to the maximum matching size
    # (all spiders can be matched to distinct cells, which is minimum they can cover)
    occupied = matching_size
    empty = total_cells - occupied

    return str(empty) + '\n'

