def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return ""

    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        u, v, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u, v, e, i))
        # Keep order of output for non-MST edges

    edges.sort(key=lambda x: x[2])

    parent = list(range(n + 1))

    def find(x):
        if parent[x] == x:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_adj = [[] for _ in range(n + 1)]
    output_order = []

    for u, v, e, idx in edges:
        if union(u, v):
            mst_adj[u].append((v, e))
            mst_adj[v].append((u, e))
        else:
            output_order.append((u, v, e, idx))

    # BFS to build tree structure
    parent_node = [0] * (n + 1)
    parent_weight = [0] * (n + 1)
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)

    queue = collections.deque([1])
    visited[1] = True
    depth[1] = 0

    while queue:
        u = queue.popleft()
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                parent_node[v] = u
                parent_weight[v] = w
                queue.append(v)

    # Binary lifting
    LOG = 20
    up = [[-1] * (n + 1) for _ in range(LOG)]
    max_w = [[-1] * (n + 1) for _ in range(LOG)]

    for v in range(1, n + 1):
        up[0][v] = parent_node[v]
        max_w[0][v] = parent_weight[v]

    for i in range(1, LOG):
        for v in range(1, n + 1):
            if up[i-1][v] != -1:
                up[i][v] = up[i-1][up[i-1][v]]
                max_w[i][v] = max(max_w[i-1][v], max_w[i-1][up[i-1][v]])
            else:
                up[i][v] = -1
                max_w[i][v] = -1

    def get_max_on_path(u, v):
        if u == v:
            return -1

        ans = 0

        if depth[v] > depth[u]:
            u, v = v, u

        diff = depth[u] - depth[v]

        for i in range(LOG):
            if (diff >> i) & 1 and max_w[i][v] != -1:
                ans = max(ans, max_w[i][v])
                v = up[i][v]

        if v == u:
            return ans

        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v] and up[i][u] != -1:
                ans = max(ans, max_w[i][u])
                ans = max(ans, max_w[i][v])
                u = up[i][u]
                v = up[i][v]

        ans = max(ans, max_w[0][u], max_w[0][v])
        return ans

    output = []
    for u, v, _, _ in output_order:
        mesh = get_max_on_path(u, v)
        output.append(str(mesh))

    return '\n'.join(output)


