from collections import defaultdict, deque
import math

def factorize(n):
    """Returns dict mapping prime -> count of occurrence in n"""
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

class Dinic:
    """Dinic's algorithm for maximum flow"""
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, capacity, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, capacity, rev_idx in self.graph[u]:
                if capacity > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, capacity, rev_idx = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and capacity > 0:
                pushed = self.dfs(v, t, min(flow, capacity), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev_idx][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        max_f = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                max_f += pushed
        return max_f

def solve(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Read pairs - they're 1-indexed in input, convert to 0-indexed
    pairs = []
    for line in lines[2:2+m]:
        parts = line.split()
        pairs.append((int(parts[0]) - 1, int(parts[1]) - 1))

    # Factorize all numbers and track where each prime appears
    pos_primes = defaultdict(lambda: defaultdict(int))
    all_primes = set()

    for i in range(n):
        factors = factorize(a[i])
        for prime, count in factors.items():
            all_primes.add(prime)
            pos_primes[i][prime] = count

    total_operations = 0

    # For each distinct prime, build flow network
    for prime in all_primes:
        # Count copies of this prime at each position
        odd_cap = {}  # 0-indexed position -> count of prime
        even_cap = {}  # 0-indexed position -> count of prime

        for i in range(n):
            count = pos_primes[i].get(prime, 0)
            # Position i (0-indexed) has 1-indexed position = i + 1
            if count > 0:
                if (i + 1) % 2 == 1:  # odd-indexed position (1-indexed)
                    odd_cap[i] = count
                else:
                    even_cap[i] = count

        # If no odd or even positions have this prime, skip
        if not odd_cap or not even_cap:
            continue

        # Build flow network
        # Nodes: 0=source, 1..len(odd_cap)=odd positions, len+1=mid, len+2..=even positions, max=sink
        dinic = Dinic(2 + len(odd_cap) + len(even_cap))
        source = 0
        sink = 2 + len(odd_cap) + len(even_cap) - 1
        odd_end = 2 + len(odd_cap)

        # Edges from source to odd positions
        for pos, cap in odd_cap.items():
            u_node = 1 + pos  # Map position to node 1..n_odd
            dinic.add_edge(source, u_node, cap)

        # Edges from even positions to sink
        for pos, cap in even_cap.items():
            v_node = odd_end + pos + 1  # Map position to node after odd_end
            dinic.add_edge(v_node, sink, cap)

        # Edges for good pairs (odd position -> even position)
        # Note: (i,j) has i+j odd, so one is odd-indexed, one is even-indexed
        for i, j in pairs:
            # Determine which is odd-indexed (1-indexed)
            i_odd = (i + 1) % 2 == 1
            j_odd = (j + 1) % 2 == 1

            # Find the connection (should be unique in direction)
            if i_odd:
                odd_pos, even_pos = i, j
            else:
