    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        return gcd, y1 - (b // a) * x1, x1

    def modInverse(a, m):
        gcd, x, y = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # Precompute factorials and inverse factorials modulo p
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i-1] * i) % p

    inv_fact = [1] * (n + 1)
    inv_fact[n] = modInverse(fact[n], p)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = (inv_fact[i+1] * (i+1)) % p

    def nCr(n_val, r_val):
        if r_val < 0 or r_val > n_val:
            return 0
        return fact[n_val] * inv_fact[r_val] % p * inv_fact[n_val - r_val] % p

    ans = 0
    # Iterate through possible values of d = a - b (final inventory)
    for d in range(l, r + 1):
        # Iterate through possible values of c (C customers)
        for c in range(n - d + 1):
