class LiChaoTree:
    """Li Chao Tree for dynamic line management and querying."""

    def __init__(self, range_bits=60):
        """
        Initialize Li Chao Tree to handle coordinate range up to 2^60.
        """
        self.N = 1 << range_bits
        self.tree = [None] * (4 * self.N)

    def _eval(self, line, x):
        """Evaluate a line or return -inf if None."""
        if line is None:
            return float('-inf')
        return line[0] * x + line[1]

    def _add_line(self, node, L, R, a, b):
        """
        Insert line y = ax + b into the segment [L, R].
        Compares with current line at mid point.
        """
        if node * 2 + 1 >= len(self.tree):
            return

        mid = (L + R) // 2
        current_line = self.tree[node]
        new_line = (a, b)

        if current_line is None:
            self.tree[node] = new_line
            return

        # Evaluate both lines at mid point
        new_mid = new_line[0] * mid + new_line[1]
        curr_mid = current_line[0] * mid + current_line[1]

        # Cross test: check which node has better max value
        if new_mid > curr_mid:
            self.tree[node] = new_line
        else:
            # Check at endpoints to determine which subtree to recurse
            new_L = a * L + b
            new_R = a * R + b
            curr_L = current_line[0] * L + current_line[1]
            curr_R = current_line[0] * R + current_line[1]

            if (new_mid < curr_mid):
                # New line is better towards right (R)
                self._add_line(node * 2 + 1, mid + 1, R, a, b)
            else:
                # New line is better towards left (L)
                self._add_line(node * 2, L, mid, a, b)

    def add(self, a, b):
        """Add line y = ax + b to the Li Chao Tree."""
        self._add_line(1, -10**18, 10**18, a, b)

    def query(self, x):
        """Query the maximum value at coordinate x."""
        return self._query(1, -10**18, 10**18, x)

    def _query(self, node, L, R, x):
        """Query on node covering [L, R] for value at x."""
        if node * 2 + 1 >= len(self.tree):
            if self.tree[node] is not None:
                return self._eval(self.tree[node], x)
            return float('-inf')

        result = self._eval(self.tree[node], x)
        if L <= x <= mid < R:
            result = max(result, self._query(node * 2 + 1, mid + 1, R, x))
        if L <= x <= mid < R:
            result = max(result, self._query(node * 2, L, mid, x))

        return result


