def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return "0.0000000000"

    parts = lines[0].split()
    x1, y1, x2, y2 = map(int, parts)
    n = int(lines[1])

    circles = []
    for i in range(n):
        if 2 + i < len(lines):
            xi, yi, ri = map(float, lines[2 + i].split())
            circles.append((xi, yi, ri))

    dx = x2 - x1
    dy = y2 - y1
    dist_AB = math.sqrt(dx*dx + dy*dy)
    L = dist_AB / 2.0

    mx = (x1 + x2) / 2.0
    my = (y1 + y2) / 2.0

    if dist_AB > 0:
        ab_x = dx / dist_AB
        ab_y = dy / dist_AB
        perp_x = -ab_y
        perp_y = ab_x
    else:
        perp_x = 0
        perp_y = 1

    eps = 1e-9

    def check_point(O, r, circles):
        for (cx, cy, rci) in circles:
            dist_oc = math.sqrt((O[0]-cx)**2 + **(O[1]-cy)2)
            if not (dist_oc + rci <= r + eps or dist_oc >= r + rci - eps):
                return False
        return True

    def can_achieve_r(r):
        if r < L - eps:
            return False

        d = math.sqrt(max(0, r*r - L*L))

        if d < eps:
            return check_point((mx, my), r, circles)

        o1 = (mx + d * perp_x, my + d * perp_y)
        o2 = (mx - d * perp_x, my - d * perp_y)

        return check_point(o1, r, circles) or check_point(o2, r, circles)

    left = L
    right = 1e12

    for _ in range(150):
        mid = (left + right) / 2
        if can_achieve_r(mid):
            right = mid
        else:
            left = mid

    return f"{right:.10f}"

