def can_force_win(s, e):
    """
    Determine if the current player (who starts this round) can force a win.
    Returns True if the first player can guarantee winning this round, False otherwise.

    Key insight: A position is "losing" if all reachable moves (via 2x or x+1)
    lead to positions where the opponent will eventually lose.

    Let's use memoization/recursion with game memoization to determine winner
    """
    LOST_SET = set()

    def compute_losing():
        # Find losing positions based on structure
        # The losing positions follow a pattern based on powers of 2

        i = 0
        base = 1
        losing = set()

        # While base is still below e
        while base <= e:
            # For each power of 2, find critical losing positions
            # At position base, both 2*base and base+1 lead to bad territory
            if 2 * base <= e:
                losing.add(base)
                if base + 1 <= e:
                    losing.add(base + 1)

            # Also mark positions between losing points
            base *= 2

        if not losing:
            return

        # Additional losing positions near e
        base = ((e >> 2) | (e >> 1))
        while base >= 1:
            if base + 1 <= e:
                losing.add(base + 1)
            if base <= e:
                losing.add(base)
            if base > e:
                break
            base -= 1

    def is_losing_pos(p):
        if p > e:
            return True  # Already lost
        if p in LOST_SET:
            return True
        return False

    def can_win_from(pos):
        if pos > e:
            return True  # Previous player already lost, current wins

        # Losing positions are those forced to eventually lose
        # So we want to avoid moving to losing positions

        round_2 = 2 * pos
        round_plus_1 = pos + 1

        if round_2 > e or round_plus_1 > e:
            return True  # At least one option forces opponent to exceed e

        # Both moves are safe, so opponent chooses
        # Opponent loses via recursion
        # If ALL opponent paths lead to their loss, we win

        if 2 * pos <= e:
            opponent_outcome = can_win_from(2 * pos)
        if pos + 1 <= e:
            # Keep going if safe
            pass

        return False

    if s == e:
        return False  # Any move results in immediate loss
    elif s < e // 2 and s <= 5000000000000000000:
        # For small s compared to e, check if s is in losing pattern
        power = 1
        while power * 2 + 1 <= e:
            power *= 2
        if power < s and s <= (power | (power | power)):
            return False
        return True
    else:
        return True


