import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    coords = []
    for i in range(n + 1):
        parts = list(map(float, lines[i + 1].split()))
        coords.append(tuple(parts))

    vp, vs = map(float, lines[n + 2].split())
    Px, Py, Pz = map(float, lines[n + 3].split())
    P = (Px, Py, Pz)

    def dist_sq(a, b):
        return (a[0] - b[0])**2 + (a[1] - b[1])**2 + (a[2] - b[2])**2

    def dist(a, b):
        return math.sqrt(dist_sq(a, b))

    # Precompute segment lengths
    seg_lens = [dist(coords[i], coords[i+1]) for i in range(n)]
    prefix_lens = [0.0] * (n + 1)
    for i in range(n):
        prefix_lens[i+1] = prefix_lens[i] + seg_lens[i]

    total_len = prefix_lens[n]

    # Check if Harry starts at the same position as the snitch
    if dist_sq(P, coords[0]) < 1e-9:
        return f"YES\n0.000000000000000\n{Px:.15f} {Py:.15f} {Pz:.15f}\n"

    def snitch_pos(t):
        """Return the position of the snitch at time t"""
        d = min(vs * t, total_len)

        for i in range(n):
            a, l = prefix_lens[i], seg_lens[i]
            if d <= a + l:
                k = (d - a) / l
                return tuple(
                    coords[i][j] + k * (coords[i+1][j] - coords[i][j]) for j in range(3)
                )
        return coords[n]

    def can_catch(t):
        """Check if Harry can reach the snitch's position at time t or earlier"""
        sp = snitch_pos(t)
        d = dist(P, sp)
        return d <= vp * t + 1e-9

    # Binary search for the minimum valid time
    left, right = 0.0, total_len / vs + 10.0

    for _ in range(100):  # Enough iterations for precision
        mid = (left + right) / 2
        if can_catch(mid):
            right = mid
        else:
            left = mid

    # Check if a solution exists
    if can_catch(right):
        t = right
        pos = snitch_pos(t)
        return f"YES\n{t:.15f}\n{pos[0]:.15f} {pos[1]:.15f} {pos[2]:.15f}\n"
    else:
        # Check if left boundary works (it should by binary search invariant)
        if can_catch(left):
            t = left
            pos = snitch_pos(t)
            return f"YES\n{t:.15f}\n{pos[0]:.15f} {pos[1]:.15f} {pos[2]:.15f}\n"
        else:
            return "NO\n"

from collections import deque

def solution(s):
    n = int(s)

    # Edge case: 0 needs 0 operations
    if n == 0:
        return "0"

    # BFS to find minimum operations
    queue = deque([(n, 0)])  # (current_number, steps)
    visited = {n}

    while queue:
        current, steps = queue.popleft()

        if current == 0:
            return str(steps)

        # Get all digits in current number
        for c in str(current):
            d = int(c)
            if d > 0:  # Can only subtract positive digits
                next_val = current - d
                if next_val not in visited:
                    visited.add(next_val)
                    queue.append((next_val, steps + 1))

    return "0"

