def solution(input_str):
    n, k = map(int, input_str.strip().split())

    def canonical(bits):
        """Return the lexicographically smallest canonical form"""
        c = tuple(bits)
        complement = tuple(1 - x for x in c)
        reverse = tuple(c[::-1])
        complement_reverse = tuple(1 - x for x in reverse)
        return min([c, complement, reverse, complement_reverse])

    # For n <= 26, we can enumerate all 2^n strings  
    if n <= 26:
        seen = set()
        representatives = []

        for i in range(1 << n):
            bits = [(i >> (n - 1 - j)) & 1 for j in range(n)]
            canon = canonical(bits)
            if canon not in seen:
                seen.add(canon)
                representatives.append(bits)

        representatives.sort(key=lambda x: tuple(x))

        if k <= len(representatives):
            return ''.join(map(str, representatives[k - 1]))
        else:
            return "-1"

    # For larger n, use DFS to find the k-th representative
    current = [0] * n
    seen = set()
    k_counter = k
    result = None

    def dfs(idx):
        nonlocal k_counter, result

        if k_counter <= 0:
            return

        if idx == n:
            canon = canonical(tuple(current))
            if canon not in seen:
                seen.add(canon)
                k_counter -= 1
                if k_counter == 0:
                    result = current[:]
            return

        # Try 0 first (lexicographically smaller)
        current[idx] = 0
        dfs(idx + 1)

        if k_counter <= 0:
            return

        # Try 1
        current[idx] = 1
        dfs(idx + 1)

    dfs(0)

    if result is not None:
        return ''.join(map(str, result))
    else:
        return "-1"


